DO $$ DECLARE f record; BEGIN FOR f IN SELECT p.oid::regprocedure signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN('can_manage_competition_vault','competition_scores_visible','redirect_legacy_competition_scores','finish_legacy_competition_scores','history_row_scores_visible','history_scores_visible','can_read_history_row','mask_history_players','history_result_dto','read_game_result','read_game_history','protect_competition_game_results','protect_competition_event_scores','sync_competition_result_to_events','save_game_history','read_history_player_stats','read_history_summary','read_history_report_events','match_scores_hidden','save_competition_match_result','sync_competition_match_events','guard_external_competition_match_edits') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',f.signature); END LOOP;END $$;
GRANT EXECUTE ON FUNCTION public.can_manage_competition_vault(uuid),public.competition_scores_visible(uuid),public.history_row_scores_visible(uuid,uuid),public.history_scores_visible(uuid),public.can_read_history_row(uuid,uuid),public.match_scores_hidden(uuid) TO anon,authenticated;
GRANT EXECUTE ON FUNCTION public.read_game_result(uuid),public.read_game_history(uuid,uuid,integer),public.save_game_history(jsonb,boolean),public.read_history_player_stats(uuid,uuid,timestamptz,timestamptz),public.read_history_summary(uuid),public.read_history_report_events(uuid),public.save_competition_match_result(uuid,integer,integer,text) TO authenticated;
CREATE POLICY service_pending_scores ON public.competition_pending_scores FOR ALL TO service_role USING(true) WITH CHECK(true);